        for [r_start, r_end] in result:
            if b_end <= r_start or b_start >= r_end:
                # No overlap
                new_result.append([r_start, r_end])
            else:
                # There is overlap, keep the non-overlapping parts
                if r_start < b_start:
                    new_result.append([r_start, b_start])
                if r_end > b_end:
                    new_result.append([b_end, r_end])
        result = new_result

    return result

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort by start position
    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0][:]]
    for [start, end] in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            # Overlapping or touching, merge them
            merged[-1][1] = max(last_end, end)
        else:
            # No overlap, add as new interval
            merged.append([start, end])

    return merged

